  "forms": [
    {
      "form_id": "signup",
      "label": "Create an account",
      "fields": [
        "display_name",
        "email",
        "password"
      ]
    },
    {
      "form_id": "new-post",
      "label": "Publish a post",
      "fields": [
        "title",
        "body",
        "author_name"
      ]
    }
  ]
}

